update public.global_settings set landing_content = jsonb_set(coalesce(landing_content, '{}'::jsonb), '{features,items}', '[{"icon":"BarChart3","title":"লাইভ প্রফিট রিপোর্ট","desc":"সেল, রেভিনিউ, ডিউ, রিটার্ন — সব রিয়েল-টাইমে।"},{"icon":"ShieldCheck","title":"ডেটা সম্পূর্ণ প্রাইভেট","desc":"প্রতিটি রিসেলারের অর্ডার ও কাস্টমার ডেটা আলাদা।"},{"icon":"Sparkles","title":"টিম ও কমিশন সিস্টেম","desc":"স্টাফ পারমিশন, লিডার রিসেলার — ইনকাম বাড়ান।"}]'::jsonb) where id = 1;